import sys

def solve():
    # Read input from stdin
    # The input format usually depends on the environment, 
    # but based on the prompt, we expect a list of integers.
    # Since the input is provided as a list in the example, 
    # we will handle reading a comma-separated or space-separated line.
    input_data = sys.stdin.read().strip()
    if not input_data:
        return

    # Clean the input string to handle cases like "[1,2,3]" or "1 2 3"
    input_data = input_data.replace('[', '').replace(']', '').replace(',', ' ')
    nums = list(map(int, input_data.split()))

    if not nums:
        print(0)
        return

    # Step 1: Count frequencies of each element
    freq_map = {}
    for num in nums:
        freq_map[num] = freq_map.get(num, 0) + 1

    # Step 2: Find the maximum frequency
    max_freq = 0
    for freq in freq_map.values():
        if freq > max_freq:
            max_freq = freq

    # Step 3: Sum frequencies of all elements that have the max_freq
    total_max_freq_elements = 0
    for freq in freq_map.values():
        if freq == max_freq:
            total_max_freq_elements += freq

    print(total_max_freq_elements)

if __name__ == "__main__":
    solve()

import sys
import ast

def solve():
    # Read input from stdin
    try:
        input_data = sys.stdin.read().strip()
        if not input_data:
            return
        # Convert the input string to a Python list
        dimensions = ast.literal_eval(input_data)
    except Exception:
        return

    max_diag_sq = -1
    max_area = -1

    for length, width in dimensions:
        # Calculate squared diagonal length to avoid floating point issues
        diag_sq = length**2 + width**2
        area = length * width

        # If we find a longer diagonal, update both max_diag_sq and max_area
        if diag_sq > max_diag_sq:
            max_diag_sq = diag_sq
            max_area = area
        # If the diagonals are equal, take the one with the maximum area
        elif diag_sq == max_diag_sq:
            if area > max_area:
                max_area = area

    print(max_area)

if __name__ == "__main__":
    solve()

import sys

def solve():
    # Read input from stdin
    line = sys.stdin.read().strip()
    if not line:
        return

    # The problem provides a string s
    # If the input is wrapped in quotes or formatted as s = "...", clean it
    s = line
    if s.startswith('s = "') and s.endswith('"'):
        s = s[5:-1]
    elif s.startswith('"') and s.endswith('"'):
        s = s[1:-1]

    # Frequency map for all characters
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    # The number of operations is the maximum frequency of any character
    max_freq = 0
    for char in counts:
        if counts[char] > max_freq:
            max_freq = counts[char]

    # We need to find characters that appear at least max_freq times.
    # Specifically, we want the last occurrence of characters that appear max_freq times,
    # and for any character that appears more than max_freq times (not possible here),
    # we'd take the occurrence at index (max_freq).
    # Actually, the simplest way: iterate backwards and pick the max_freq-th occurrence.

    result = []
    current_counts = {}
    for char in reversed(s):
        current_counts[char] = current_counts.get(char, 0) + 1
        if current_counts[char] == max_freq:
            result.append(char)

    # The result is collected backwards, so reverse it to get original order
    print("".join(reversed(result)))

if __name__ == "__main__":
    solve()

import sys

def solve():
    # Read input from stdin
    # The input might be provided as a quoted string or just the string itself
    # based on common competitive programming formats.
    line = sys.stdin.read().strip()
    if not line:
        return

    # Handle cases where input might be passed as s = "string"
    if line.startswith('s = "') and line.endswith('"'):
        s = line[5:-1]
    elif line.startswith('"') and line.endswith('"'):
        s = line[1:-1]
    else:
        s = line

    # The logic to count key changes
    changes = 0
    for i in range(1, len(s)):
        # Compare characters in lowercase to ignore case differences
        if s[i].lower() != s[i-1].lower():
            changes += 1

    print(changes)

