    # Read input from standard input
    try:
        line = sys.stdin.readline()
        if not line:
            return
        n, x, y, z = map(int, line.split())
    except ValueError:
        return

    # The train travels from X to Y.
    # If X < Y, it's an inbound train (stops at X, X+1, ..., Y)
    # If X > Y, it's an outbound train (stops at X, X-1, ..., Y)
    # Since X, Y, Z are distinct, Z is visited if it's between X and Y.

