    n = len(s)
    # dp[i] will store the minimum number of balanced substrings for s[0...i-1]
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        # We check all possible substrings ending at i: s[j...i-1]
        # To optimize, we can maintain character counts as we decrease j
        counts = {}
