        # parts[0] is C_i (number of keys)
        # parts[1...C_i] are the keys A_{i,j}
        # parts[C_i + 1] is the result R_i
        c_i = int(parts[0])
        keys = [int(x) for x in parts[1:c_i+1]]
        result = parts[c_i+1]

        # Convert keys to a bitmask (0-indexed)
        mask = 0
        for key in keys:
            mask |= (1 << (key - 1))

        tests.append((mask, result))

    count = 0
    # Iterate through all 2^N possible combinations of real/dummy keys
    # A bit set to 1 means the key is real, 0 means it is a dummy.
    for i in range(1 << n):
        possible = True
        for mask, result in tests:
            # Count how many real keys are in the current test set
            # i & mask gives the bits that are set in both the combination and the test set
            real_keys_count = bin(i & mask).count('1')

            if result == 'o':
                # Door opens if at least K real keys are inserted
                if real_keys_count < k:
                    possible = False
                    break
            else: # result == 'x'
                # Door does not open if fewer than K real keys are inserted
                if real_keys_count >= k:
                    possible = False
                    break

        if possible:
            count += 1

    print(count)

if __name__ == "__main__":
    solve()

