def solve():
    # Read N from standard input
    line = sys.stdin.readline()
    if not line:
        return
    n = int(line.strip())

    # A level-0 carpet is a single black cell
    carpet = [['#']]

    # Iteratively build level-K carpet from level-(K-1) carpet
    for k in range(1, n + 1):
        prev_size = 3**(k-1)
        current_size = 3**k
        # Initialize current carpet with white cells
        new_carpet = [['.' for _ in range(current_size)] for _ in range(current_size)]

        # Fill the 8 surrounding blocks with the previous level's carpet
        for r_block in range(3):
            for c_block in range(3):
                # The central block (1, 1) remains white
                if r_block == 1 and c_block == 1:
                    continue

                # Copy the prev_size x prev_size carpet into the block
                start_r = r_block * prev_size
                start_c = c_block * prev_size
                for r in range(prev_size):
                    for c in range(prev_size):
                        new_carpet[start_r + r][start_c + c] = carpet[r][c]

        carpet = new_carpet

    # Print the final carpet
    for row in carpet:
        print("".join(row))

