import sys

def solve():
    # Read input from stdin
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        # Expecting input like [1,2,3] or 1 2 3
        if line.startswith('['):
            nums = eval(line)
        else:
            nums = list(map(int, line.split()))
    except EOFError:
        return

    # Convert each number to its binary representation string
    bin_nums = [bin(n)[2:] for n in nums]

    max_val = 0

    # Generate all permutations of the binary strings
    for p in itertools.permutations(bin_nums):
        # Concatenate the strings in the current permutation order
        concat_bin = "".join(p)
        # Convert the binary string back to a decimal integer
        val = int(concat_bin, 2)
        # Update the maximum value found so far
        if val > max_val:
            max_val = val

    print(max_val)

