import sys
from collections import deque

def solve():
    # Read H, W, D from the first line of input
    try:
        line1 = sys.stdin.readline().split()
        if not line1:
            return
        h, w, d = map(int, line1)
    except ValueError:
        return

    grid = []
    for _ in range(h):
        grid.append(sys.stdin.readline().strip())

    # distance array to keep track of the minimum distance from any humidifier
    # Initialize with a value larger than any possible distance
    dist = [[-1] * w for _ in range(h)]
    queue = deque()

    # Find all humidifiers and add them to the queue as starting points
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 'H':
                dist[i][j] = 0
                queue.append((i, j))

    # BFS to find all reachable cells within distance D
    # Use a deque for standard BFS since all edge weights are 1
    while queue:
        r, c = queue.popleft()

        # If we have reached the distance limit, we don't expand further
        if dist[r][c] >= d:
            continue

        # Explore 4-connectivity neighbors
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc

            # Check boundaries and if the cell is a wall or already visited
            if 0 <= nr < h and 0 <= nc < w:
                if grid[nr][nc] != '#' and dist[nr][nc] == -1:
                    dist[nr][nc] = dist[r][c] + 1
                    queue.append((nr, nc))

    # Count the number of humidified floor cells (including 'H' cells)
    count = 0
    for i in range(h):
        for j in range(w):
            # A cell is humidified if it's not a wall and its distance is <= D
            # Note: dist[i][j] == -1 means it was not reachable
            if grid[i][j] != '#' and dist[i][j] != -1 and dist[i][j] <= d:
                count += 1

    print(count)

if __name__ == "__main__":
    solve()

