import sys

def solve():
    line = sys.stdin.readline()
    if not line:
        return
    n = int(line.strip())

    m = int(n**0.5)
    # Adjust m to be exactly floor(sqrt(n))
    if (m + 1)**2 <= n:
        m += 1
    elif m**2 > n:
        m -= 1

    # Sieve primes up to m
    primes = []
    is_prime = [True] * (m + 1)
    for p in range(2, m + 1):
        if is_prime[p]:
            primes.append(p)
            for i in range(p * p, m + 1, p):
                is_prime[i] = False

    count = 0

    # Case 1: p^8 <= n
    # p <= n^(1/8)
    # Since n <= 4*10^12, p <= (4*10^12)^(1/8) approx 37.6
    for p in primes:
        if p**8 <= n:
            count += 1
        else:
            break

    # Case 2: p^2 * q^2 <= n  => pq <= sqrt(n) = m
    # We need p < q and pq <= m
    # For a fixed p, q must be in range (p, m/p]
    # The number of such q is (number of primes <= m/p) - (number of primes <= p)

    # Precompute prime counts for fast lookup
    # prime_count[x] = number of primes <= x
    prime_count = [0] * (m + 1)
    curr = 0
    for i in range(m + 1):
        if i >= 2 and is_prime[i]:
            curr += 1
        prime_count[i] = curr

    for p in primes:
        if p * p >= m:
            break
        # We need q > p and q <= m // p
        upper = m // p
        if upper > p:
            count += (prime_count[upper] - prime_count[p])

    print(count)

if __name__ == "__main__":
    solve()

