def solve():
    # Read the input from stdin
    input_data = sys.stdin.read().strip()
    if not input_data:
        return

    try:
        # Convert the input string representation of a list to an actual list
        events = ast.literal_eval(input_data)
    except:
        return

    max_time = -1
    result_index = float('inf')

    for i in range(len(events)):
        index_i = events[i][0]
        time_i = events[i][1]

        # Calculate duration
        if i == 0:
            duration = time_i
        else:
            duration = time_i - events[i-1][1]

        # Update result based on duration and index
        if duration > max_time:
            max_time = duration
            result_index = index_i
        elif duration == max_time:
            if index_i < result_index:
                result_index = index_i

    print(result_index)

