    snakes = []
    for _ in range(n):
        try:
            line = sys.stdin.readline().split()
            if not line:
                break
            t = int(line[0])
            l = int(line[1])
            snakes.append((t, l))
        except (ValueError, IndexError):
            break

    # For each k from 1 to D, calculate the maximum weight
    for k in range(1, d + 1):
        max_weight = -1
        for t, l in snakes:
            # Current weight = thickness * (original length + k)
            current_weight = t * (l + k)
            if current_weight > max_weight:
                max_weight = current_weight
        print(max_weight)

