        if not line2:
            return
        a = list(map(int, line2.split()))
    except ValueError:
        return

    # A sequence of length 2 is always a geometric progression
    # since there is always a ratio r = A2/A1.
    if n == 2:
        print("Yes")
        return

    # For n > 2, check if A_{i+1}/A_i is constant.
    # A_{i+1}/A_i = A_2/A_1  =>  A_{i+1} * A_1 = A_i * A_2
    is_geometric = True
    for i in range(1, n - 1):
        if a[i+1] * a[0] != a[i] * a[1]:
            is_geometric = False
            break

    if is_geometric:
        print("Yes")
    else:
        print("No")

