import sys

def solve():
    # Read N and M from the first line of input
    try:
        line1 = sys.stdin.readline().split()
        if not line1:
            return
        n, m = map(int, line1)
    except ValueError:
        return

    # Read grid S (N lines)
    s = []
    for _ in range(n):
        s.append(sys.stdin.readline().strip())

    # Read grid T (M lines)
    t = []
    for _ in range(m):
        t.append(sys.stdin.readline().strip())

    # Iterate through all possible top-left corners (a, b)
    # a and b are 1-indexed in the problem description
    # In 0-indexing, a ranges from 0 to N-M and b ranges from 0 to N-M
    for a in range(n - m + 1):
        for b in range(n - m + 1):
            match = True
            # Check if the subgrid of S starting at (a, b) matches T
            for i in range(m):
                for j in range(m):
                    if s[a + i][b + j] != t[i][j]:
                        match = False
                        break
                if not match:
                    break

            if match:
                # Output 1-indexed coordinates
                print(f"{a + 1} {b + 1}")
                return

if __name__ == "__main__":
