import sys

def solve():
    # Read the input string S
    try:
        s = sys.stdin.read().strip()
    except EOFError:
        return

    if not s:
        # Depending on interpretation, an empty string is usually a valid bracket sequence.
        # However, constraints say length is between 1 and 2*10^5.
        print("Yes")
        return

    # Use a stack to simulate the deletion of contiguous matching pairs.
    # This is the standard algorithm for checking balanced bracket sequences.
    stack = []

    # Map of closing brackets to their corresponding opening brackets.
    mapping = {')': '(', ']': '[', '>': '<'}

    for char in s:
        if char in mapping:
            # If the current character is a closing bracket, check if the stack
            # is not empty and the top of the stack is the matching opening bracket.
            if stack and stack[-1] == mapping[char]:
                stack.pop()
            else:
                # If it doesn't match or stack is empty, it's not a colorful bracket sequence.
                print("No")
                return
        else:
            # If it's an opening bracket, push it onto the stack.
            stack.append(char)

    # After processing the entire string, the stack must be empty for it to be a colorful sequence.
    if not stack:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
