    a = input_data[1:]

    # last_pos stores the last index where each number was encountered
    last_pos = {}
    min_length = float('inf')

    for i in range(n):
        val = a[i]
        if val in last_pos:
            # Calculate length of subarray from previous occurrence to current
            length = i - last_pos[val] + 1
            if length < min_length:
