import ast

def solve():
    # Read all input
    input_text = sys.stdin.read()
    if not input_text:
        return

    # Try to find lists in the input text
    # This handles "groups = [8,4,3,2,4]\nelements = [4,2]"
    try:
        # Split by lines and find the lines containing '='
        lines = input_text.splitlines()
        groups = []
        elements = []
        for line in lines:
            if 'groups' in line and '=' in line:
                groups = ast.literal_eval(line.split('=')[1].strip())
            elif 'elements' in line and '=' in line:
                elements = ast.literal_eval(line.split('=')[1].strip())

        if not groups or not elements:
            # Fallback: just find all lists in the text
            import re
            lists = re.findall(r'\[.*?\]', input_text)
            if len(lists) >= 2:
                groups = ast.literal_eval(lists[0])
                elements = ast.literal_eval(lists[1])
    except:
        return

    MAX_VAL = 100000
    best_index = [-1] * (MAX_VAL + 1)
    seen_val = [False] * (MAX_VAL + 1)

    for j, val in enumerate(elements):
        if val <= MAX_VAL and not seen_val[val]:
            seen_val[val] = True
            for multiple in range(val, MAX_VAL + 1, val):
                if best_index[multiple] == -1:
                    best_index[multiple] = j

    print([best_index[g] if g <= MAX_VAL else -1 for g in groups])

