import sys

def solve():
    # Read input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    s = input_data[0]
    k = int(input_data[1])
    n = len(s)

    if k == 0:
        print("true")
        return

    # Step 1: Find first and last occurrences of each character
    first = {}
    last = {}
    for i, char in enumerate(s):
        if char not in first:
            first[char] = i
        last[char] = i

    # Step 2: Find all valid "special" substrings
    intervals = []
    chars_present = list(first.keys())

    for char in chars_present:
        l = first[char]
        r = last[char]

        # Expand the range [l, r] to include all occurrences of characters inside it
        possible = True
        while True:
            expanded = False
            for i in range(l, r + 1):
                c = s[i]
                if first[c] < l:
                    l = first[c]
                    expanded = True
                if last[c] > r:
                    r = last[c]
                    expanded = True
            if not expanded:
                break

        # Condition: Not the entire string
        if not (l == 0 and r == n - 1):
            intervals.append((l, r))

    # Step 3: Find the maximum number of disjoint intervals (Greedy)
    # Sort by end time
    intervals.sort(key=lambda x: x[1])

    count = 0
    last_end = -1
    for l, r in intervals:
        if l > last_end:
            count += 1
            last_end = r

    if count >= k:
        print("true")
    else:
        print("false")

