def solve():
    # Reading input from stdin
    # The input format is expected to be a list representation like [1,2,4]
    # or space separated integers. Let's handle common formats.
    try:
        line = sys.stdin.read().strip()
        if not line:
            return

        # Handle [1,2,3] format
        if line.startswith('[') and line.endswith(']'):
            line = line[1:-1]

        # Split by comma or space and convert to integers
        if ',' in line:
            nums = [int(x.strip()) for x in line.split(',') if x.strip()]
        else:
            nums = [int(x.strip()) for x in line.split() if x.strip()]

        if not nums:
            return

        n = len(nums)
        max_diff = 0

        # Check adjacent elements in the linear part of the array
        for i in range(n - 1):
            diff = abs(nums[i] - nums[i+1])
            if diff > max_diff:
                max_diff = diff

        # Check the circular connection (last and first element)
        circular_diff = abs(nums[n-1] - nums[0])
        if circular_diff > max_diff:
            max_diff = circular_diff

        print(max_diff)

    except EOFError:
        pass
    except Exception:
        pass

