def solve():
    # Read input from stdin
    input_data = sys.stdin.read().strip()
    if not input_data:
        return

    # The input might be passed as a string directly or inside quotes
    # Cleaning input in case it's provided as "s = '...'"
    s = input_data
    if s.startswith('s = "') and s.endswith('"'):
        s = s[5:-1]
    elif s.startswith('s = \'') and s.endswith('\''):
        s = s[5:-1]
    elif s.startswith('"') and s.endswith('"'):
        s = s[1:-1]
    elif s.startswith("'") and s.endswith("'"):
        s = s[1:-1]

    # Pre-calculate frequencies of each digit in the string
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    # Iterate through the string to find the first valid pair
    for i in range(len(s) - 1):
        d1 = s[i]
        d2 = s[i+1]

        # Condition 1: The first digit is not equal to the second
        if d1 != d2:
            # Condition 2: Each digit appears as many times as its numeric value
            val1 = int(d1)
            val2 = int(d2)
            if counts.get(d1, 0) == val1 and counts.get(d2, 0) == val2:
                print(d1 + d2)
                return

    # If no valid pair is found, return an empty string
    print("")

