            # Check left neighbor at index i - k
            if i - k >= 0:
                if nums[i] <= nums[i - k]:
                    is_good = False

            # Check right neighbor at index i + k
            if is_good and i + k < n:
                if nums[i] <= nums[i + k]:
                    is_good = False

            if is_good:
                total_sum += nums[i]

        print(total_sum)

