import sys

def solve():
    # Read input from stdin
    # The input format is expected to be a list representation like [4,3,2,1]
    # Since the problem is framed as a function, we handle standard input parsing.
    input_data = sys.stdin.read().strip()
    if not input_data:
        return

    # Parsing the input string into a list of integers
    # Removing brackets and splitting by comma
    try:
        cleaned_input = input_data.replace('[', '').replace(']', '').replace(' ', '')
        if not cleaned_input:
            nums = []
        else:
            nums = [int(x) for x in cleaned_input.split(',')]
    except ValueError:
        return

    # Step 1: Replace even numbers with 0 and odd numbers with 1
    transformed = []
    for num in nums:
        if num % 2 == 0:
            transformed.append(0)
        else:
            transformed.append(1)

    # Step 2: Sort the modified array in non-decreasing order
    transformed.sort()

    # Print the resulting array in the required format
    print(transformed)

if __name__ == "__main__":
    solve()
